-- panel: team-year starters overall by unit
select year, team, unit, count(*) n, round(avg(overall),2) ovr from (select s.year, s.team, case when p.player__position in ('OT','IOL') then 'OL' when p.player__position in ('DT','EDGE') then 'DL' when p.player__position in ('CB','S') then 'DB' else p.player__position end unit, h.overall from people__pro__seasons s join people p on p._row = s._parent join people__player__history h on h._parent = s._parent and h.age = s.year - p.class_of + 18 where s.starts >= 8 and h.level = 'NFL' union all select s.year, s.team, case when a.player__position in ('OT','IOL') then 'OL' when a.player__position in ('DT','EDGE') then 'DL' when a.player__position in ('CB','S') then 'DB' else a.player__position end, h.overall from alumni__pro__seasons s join alumni a on a._row = s._parent join alumni__player__history h on h._parent = s._parent and h.age = s.year - a.class_of + 18 where s.starts >= 8 and h.level = 'NFL') where year between 2026 and 2035 and unit in ('OL','DL','LB','DB','RB','QB','WR','TE') group by year, team, unit order by year, team, unit
-- panel: team-year offense and defense run and pass yards a play
select season, team, sum(case when key='o|kind|run' then plays end) o_run_n, round(1.0*sum(case when key='o|kind|run' then yards end)/sum(case when key='o|kind|run' then plays end),3) o_run, round(1.0*sum(case when key='d|kind|run' then yards end)/sum(case when key='d|kind|run' then plays end),3) d_run, round(1.0*sum(case when key='o|kind|pass' then yards end)/sum(case when key='o|kind|pass' then plays end),3) o_pass, round(1.0*sum(case when key='d|kind|pass' then yards end)/sum(case when key='d|kind|pass' then plays end),3) d_pass from log_team_situations where level='nfl' and season between 2026 and 2035 group by season, team order by season, team
